```cpp
#include <iostream>
#include <vector>
using namespace std;

// 题面功能写在外部函数里
vector<long long> solve(int n, const vector<int>& a, const vector<vector<int>>& graph) {
    vector<int> tin(n + 1), tout(n + 1), eulerVal(n + 1);
    int timer = 0;

    // 非递归 DFS
    struct Node {
        int u, fa, state; // state: 0=首次到达, 1=退出节点
    };

    vector<Node> st;
    st.push_back({1, 0, 0});

    while (!st.empty()) {
        Node cur = st.back();
        st.pop_back();

        int u = cur.u;
        int fa = cur.fa;
        int state = cur.state;

        if (state == 0) {
            ++timer;
            tin[u] = timer;
            eulerVal[timer] = a[u];

            // 退出时处理 tout
            st.push_back({u, fa, 1});

            // 子节点入栈
            for (int v : graph[u]) {
                if (v != fa) {
                    st.push_back({v, u, 0});
                }
            }
        } else {
            tout[u] = timer;
        }
    }

    vector<long long> ans(n + 1, 0);
    const int B = 20; // 因为 a[i] <= 10^6

    // 按位统计贡献
    for (int b = 0; b < B; b++) {
        vector<int> pre(n + 1, 0);

        // 当前位的前缀和
        for (int i = 1; i <= n; i++) {
            pre[i] = pre[i - 1] + ((eulerVal[i] >> b) & 1);
        }

        long long bitValue = 1LL << b;

        // 计算每个点子树在这一位上的贡献
        for (int u = 1; u <= n; u++) {
            int l = tin[u];
            int r = tout[u];
            int ones = pre[r] - pre[l - 1];
            int size = r - l + 1;
            int zeros = size - ones;
            ans[u] += 1LL * ones * zeros * bitValue;
        }
    }

    return ans;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<int> a(n + 1);
    for (int i = 1; i <= n; i++) {
        cin >> a[i];
    }

    vector<vector<int>> graph(n + 1);
    for (int i = 0; i < n - 1; i++) {
        int u, v;
        cin >> u >> v;
        graph[u].push_back(v);
        graph[v].push_back(u);
    }

    vector<long long> ans = solve(n, a, graph);

    for (int i = 1; i <= n; i++) {
        if (i > 1) cout << ' ';
        cout << ans[i];
    }
    cout << '\n';

